// frozen, so it stays out of ux_bank_transactions_fingerprint.
func (q *Queries) TreatAsDistinct(ctx context.Context, arg TreatAsDistinctParams) (int64, error) {
	result, err := q.db.Exec(ctx, treatAsDistinct, arg.SuggestedInvoiceID, arg.ID)
	if err != nil {
		return 0, err
	}
	return result.RowsAffected(), nil
}

const twinsOf = `-- name: TwinsOf :many
SELECT DISTINCT ON (l.id) l.id AS line_id, t.id, t.bank_file_id, t.line_ref, t.format, t.account, t.direction, t.negative, t.booked_on, t.value_on, t.ordered_on, t.amount, t.currency, t.kid, t.remittance_text, t.debtor_name, t.debtor_account, t.archive_ref, t.bank_code, t.fingerprint, t.ordinal, t.duplicate_of_id, t.status, t.reason, t.suggested_invoice_id, t.resolution, t.resolved_by_user_id, t.resolved_at, t.resolution_note,
       EXISTS (SELECT 1 FROM invoices.bank_transaction_events e
               WHERE e.bank_transaction_id = t.id AND e.event = 'reversed') AS twin_reversed
FROM invoices.bank_transactions l
JOIN invoices.bank_transactions t
  ON t.id <> l.id
 AND (t.id = l.duplicate_of_id
      OR (l.duplicate_of_id IS NULL AND t.account = l.account AND t.booked_on = l.booked_on AND t.amount = l.amount
          AND t.kid IS NOT DISTINCT FROM l.kid AND t.bank_file_id <> l.bank_file_id AND t.status IN ('matched', 'resolved')))
WHERE l.id = ANY($1::bigint[])
ORDER BY l.id,
         coalesce(t.id = l.duplicate_of_id, false) DESC,
         (EXISTS (SELECT 1 FROM invoices.payments p WHERE p.bank_transaction_id = t.id AND p.removed_at IS NULL)
          OR EXISTS (SELECT 1 FROM invoices.charge_payments c WHERE c.bank_transaction_id = t.id AND c.removed_at IS NULL)) DESC,
         t.id
`

type TwinsOfRow struct {
	LineID                  int64
	InvoicesBankTransaction InvoicesBankTransaction
	TwinReversed            bool
}

// TwinsOf is, per possible duplicate or duplicate line, the line it may
// repeat (D5): the one it was kept as a duplicate of, or else the earliest
// matched or resolved line of another file with the same account, booking
// day, amount and KID — one with a live payment or charge payment first —
// and whether a reversal took back a payment of it (its reversed event).
func (q *Queries) TwinsOf(ctx context.Context, ids []int64) ([]TwinsOfRow, error) {
	rows, err := q.db.Query(ctx, twinsOf, ids)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	var items []TwinsOfRow
	for rows.Next() {
		var i TwinsOfRow
		if err := rows.Scan(
			&i.LineID,
			&i.InvoicesBankTransaction.ID,
			&i.InvoicesBankTransaction.BankFileID,
			&i.InvoicesBankTransaction.LineRef,
			&i.InvoicesBankTransaction.Format,
			&i.InvoicesBankTransaction.Account,
			&i.InvoicesBankTransaction.Direction,
			&i.InvoicesBankTransaction.Negative,
			&i.InvoicesBankTransaction.BookedOn,
			&i.InvoicesBankTransaction.ValueOn,
			&i.InvoicesBankTransaction.OrderedOn,
			&i.InvoicesBankTransaction.Amount,
			&i.InvoicesBankTransaction.Currency,
			&i.InvoicesBankTransaction.Kid,
			&i.InvoicesBankTransaction.RemittanceText,
			&i.InvoicesBankTransaction.DebtorName,
			&i.InvoicesBankTransaction.DebtorAccount,
			&i.InvoicesBankTransaction.ArchiveRef,
			&i.InvoicesBankTransaction.BankCode,
			&i.InvoicesBankTransaction.Fingerprint,
			&i.InvoicesBankTransaction.Ordinal,
			&i.InvoicesBankTransaction.DuplicateOfID,
			&i.InvoicesBankTransaction.Status,
			&i.InvoicesBankTransaction.Reason,
			&i.InvoicesBankTransaction.SuggestedInvoiceID,
			&i.InvoicesBankTransaction.Resolution,
			&i.InvoicesBankTransaction.ResolvedByUserID,
			&i.InvoicesBankTransaction.ResolvedAt,
			&i.InvoicesBankTransaction.ResolutionNote,
			&i.TwinReversed,
		); err != nil {
			return nil, err
		}
		items = append(items, i)
	}
	if err := rows.Err(); err != nil {
		return nil, err
	}
	return items, nil
}
